package app.zhijian.notes;
import app.zhijian.notes.data.RecordValidator;
import app.zhijian.notes.backup.ArchivePolicy;
import app.zhijian.notes.backup.MergePlanner;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class CoreTest {
 private final String id="4ca8e830-e9ce-44af-8916-b879a5e88981";
 private JSONObject note(String title) throws Exception {return new JSONObject().put("id",id).put("title",title).put("mode","markdown").put("content","你好").put("tags",new JSONArray().put(" 学习 ").put("学习"));}
 private JSONObject snapshot(JSONObject n) throws Exception{return new JSONObject().put("format","paper-notes").put("version",1).put("notes",new JSONArray().put(n)).put("todos",new JSONArray()).put("folders",new JSONArray()).put("media",new JSONObject());}
 @Test public void validatesChineseAndDeduplicatesTags() throws Exception {JSONObject n=RecordValidator.note(note("中文笔记"));assertEquals("中文笔记",n.getString("title"));assertEquals(1,n.getJSONArray("tags").length());assertEquals("学习",n.getJSONArray("tags").getString(0));}
 @Test public void refusesUnknownEditorType() throws Exception {try{RecordValidator.note(note("a").put("mode","script"));fail();}catch(IllegalArgumentException expected){assertTrue(expected.getMessage().contains("编辑"));}}
 @Test public void refusesTraversalAndZipBombs() {for(String p:new String[]{"../x","/etc/x","media/../../x","C:/x","media\\x"}){try{ArchivePolicy.validateEntry(p,1);fail(p);}catch(IllegalArgumentException expected){}}try{ArchivePolicy.validateEntry("media/a.png",21L*1024*1024);fail();}catch(IllegalArgumentException expected){}}
 @Test public void duplicateImportSkipsAndConflictsPreserveBoth() throws Exception {JSONObject current=snapshot(note("原始"));JSONObject result=MergePlanner.plan(current,snapshot(note("原始")));assertEquals(1,result.getJSONArray("notes").length());result=MergePlanner.plan(current,snapshot(note("新内容")));assertEquals(2,result.getJSONArray("notes").length());assertEquals("原始",result.getJSONArray("notes").getJSONObject(0).getString("title"));assertNotEquals(id,result.getJSONArray("notes").getJSONObject(1).getString("id"));}
 @Test public void conflictingMediaIsRewrittenOnlyInImportedCopy() throws Exception {JSONObject current=snapshot(note("原始").put("content","![](media/a.png)"));current.getJSONObject("media").put("a.png","aaa");JSONObject incoming=snapshot(note("导入").put("content","![](media/a.png)"));incoming.getJSONObject("media").put("a.png","bbb");JSONObject merged=MergePlanner.plan(current,incoming);assertEquals("![](media/a.png)",merged.getJSONArray("notes").getJSONObject(0).getString("content"));assertFalse(merged.getJSONArray("notes").getJSONObject(1).getString("content").contains("media/a.png"));}
 @Test public void stringsWithSeparatorsRemainDistinctDuringMerge() throws Exception {assertNotEquals(MergePlanner.canonical(new JSONArray().put("a,b").put("c")),MergePlanner.canonical(new JSONArray().put("a").put("b,c")));}
 @Test public void reimportOfConflictingFolderAndImageIsIdempotent() throws Exception {String folder="5ca8e830-e9ce-44af-8916-b879a5e88981";JSONObject current=snapshot(note("本地").put("folderId",folder));current.getJSONArray("folders").put(new JSONObject().put("id",folder).put("name","本地文件夹"));current.getJSONObject("media").put("a.png","local-hash");JSONObject incoming=snapshot(note("导入").put("folderId",folder).put("content","![](media/a.png)"));incoming.getJSONArray("folders").put(new JSONObject().put("id",folder).put("name","导入文件夹"));incoming.getJSONObject("media").put("a.png","import-hash");JSONObject once=MergePlanner.plan(current,incoming),twice=MergePlanner.plan(once,incoming);assertEquals(2,twice.getJSONArray("folders").length());assertEquals(2,twice.getJSONArray("notes").length());assertEquals(2,twice.getJSONObject("media").length());assertEquals(once.getJSONArray("notes").getJSONObject(1).getString("folderId"),twice.getJSONArray("notes").getJSONObject(1).getString("folderId"));}
}
